<?php
require __DIR__.'/config.php';
$students=$pdo->query('SELECT s.*, COUNT(f.id) AS file_count FROM students s LEFT JOIN student_files f ON f.student_id=s.id GROUP BY s.id ORDER BY s.created_at DESC')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Admin</title><link rel="stylesheet" href="style.css"></head><body><header><h1>Student Administration</h1><a class="button" href="student.php">+ Add student</a></header><main><p>Manage student records and uploaded profile documents.</p><div class="table-wrap"><table><thead><tr><th>Name</th><th>Roll no.</th><th>Email</th><th>Course</th><th>Files</th><th>Actions</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><?=h($s['name'])?></td><td><?=h($s['roll_number'])?></td><td><?=h($s['email'])?></td><td><?=h($s['course'])?></td><td><?=(int)$s['file_count']?></td><td><a href="view.php?id=<?=(int)$s['id']?>">View</a> · <a href="student.php?id=<?=(int)$s['id']?>">Edit</a> · <form class="inline" method="post" action="delete.php" onsubmit="return confirm('Delete this student?')"><input type="hidden" name="id" value="<?=(int)$s['id']?>"><button class="link-button" type="submit">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$students): ?><tr><td colspan="6">No students yet. Add the first record.</td></tr><?php endif; ?></tbody></table></div></main></body></html>
